import cupy as cp


def lowpass(images, radius):
    B, H, W = images.shape

    def idx(L):
        i = cp.arange(L)
        return cp.where(i <= (L - 1) // 2, i, i - L)

    my = cp.abs(idx(H)) <= radius
    mx = cp.abs(idx(W)) <= radius
    mask = my[:, None] & mx[None, :]

    F = cp.fft.fft2(images, axes=(-2, -1))
    F = F * mask[None, :, :]
    out = cp.fft.ifft2(F, axes=(-2, -1)).real
    return out.astype(cp.float32)

