import cupy as cp


def _fallback(A):
    n = A.shape[0]
    H = A.astype(cp.float64).copy()
    out = []
    m = n
    it = 0
    while m > 0:
        if m == 1:
            out.append(complex(H[0, 0].get()))
            break
        sub = abs(float(H[m - 1, m - 2]))
        scale = abs(float(H[m - 1, m - 1])) + abs(float(H[m - 2, m - 2])) + 1e-300
        if sub < 1e-14 * scale:
            out.append(complex(H[m - 1, m - 1].get()))
            m -= 1
            H = H[:m, :m]
            it = 0
            continue
        if m == 2 or it > 500:
            if m == 2:
                a, b, c, d = [float(x) for x in H[:2, :2].ravel().get()]
                tr = a + d
                det = a * d - b * c
                disc = complex(tr * tr / 4 - det) ** 0.5
                out.append(tr / 2 + disc)
                out.append(tr / 2 - disc)
                break
        # Rayleigh/Wilkinson-style real shift
        mu = H[m - 1, m - 1]
        Q, R = cp.linalg.qr(H - mu * cp.eye(m))
        H = R @ Q + mu * cp.eye(m)
        it += 1
        if it > 3000:
            break
    return cp.asarray(out, dtype=cp.complex128)


def eigenvalues(A):
    try:
        w = cp.linalg.eigvals(A)
        return w.astype(cp.complex128)
    except Exception:
        try:
            w, _ = cp.linalg.eig(A)
            return w.astype(cp.complex128)
        except Exception:
            return _fallback(A)
