def poisson_1d(f, h):
    f = cp.asarray(f, dtype=cp.float64)
    n = f.shape[0]
    if n == 0:
        return cp.zeros(0, dtype=cp.float64)
    inv = 1.0 / (h * h)
    main = cp.full(n, 2.0 * inv, dtype=cp.float64)
    off = cp.full(n, -1.0 * inv, dtype=cp.float64)
    A = sp.dia_matrix((cp.stack([off, main, off]), cp.array([-1, 0, 1])),
                      shape=(n, n)).tocsr()
    maxiter = max(10 * n, 1000)
    try:
        u, info = spla.cg(A, f, tol=1e-10, maxiter=maxiter)
    except TypeError:
        u, info = spla.cg(A, f, rtol=1e-10, maxiter=maxiter)
    if info != 0:
        raise RuntimeError("CG did not converge")
    return u.astype(cp.float64, copy=False)

