def _int_freqs(L):
    p = cp.arange(L)
    return cp.where(p >= (L + 1) // 2, p - L, p)


def lowpass(images, radius):
    B, H, W = images.shape
    F = cp.fft.fft2(images, axes=(-2, -1))
    my = cp.abs(_int_freqs(H)) <= radius
    mx = cp.abs(_int_freqs(W)) <= radius
    mask = my[:, None] & mx[None, :]
    F = F * mask[None, :, :]
    out = cp.fft.ifft2(F, axes=(-2, -1)).real
    return out.astype(cp.float32)

